{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2136-12-24 02:30:00",
      "speaker": "Doctor",
      "text": "Mr. ___, I’m Dr. ___. You’re in the hospital because your family found you having trouble breathing. We’re going to help you get through this."
    },
    {
      "turn_number": 2,
      "time": "2136-12-24 02:32:00",
      "speaker": "Patient",
      "text": "Can’t… breathe… trach… blocked?"
    },
    {
      "turn_number": 3,
      "time": "2136-12-24 02:34:00",
      "speaker": "Doctor",
      "text": "Yes, your trachea was very narrowed. Your CO2 was extremely high. We had to sedate you quickly and take you to the operating room."
    },
    {
      "turn_number": 4,
      "time": "2136-12-24 02:36:00",
      "speaker": "Patient",
      "text": "Was it… the stent again?"
    },
    {
      "turn_number": 5,
      "time": "2136-12-24 02:38:00",
      "speaker": "Doctor",
      "text": "No stent this time. The interventional pulmonologist found a fibrous clot blocking your airway. They dilated your trachea and cleared it out."
    },
    {
      "turn_number": 6,
      "time": "2136-12-24 02:40:00",
      "speaker": "Patient",
      "text": "Felt… like I was choking… after I vomited."
    },
    {
      "turn_number": 7,
      "time": "2136-12-24 02:42:00",
      "speaker": "Doctor",
      "text": "Yes, your family said you were trying to go to the bathroom, vomited, and then couldn’t breathe. That’s likely what triggered the blockage."
    },
    {
      "turn_number": 8,
      "time": "2136-12-24 02:44:00",
      "speaker": "Patient",
      "text": "Am I… safe now?"
    },
    {
      "turn_number": 9,
      "time": "2136-12-24 02:46:00",
      "speaker": "Doctor",
      "text": "You’re stable now. Your breathing numbers are much better. We’re watching you closely in the ICU."
    },
    {
      "turn_number": 10,
      "time": "2136-12-24 06:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your blood work showed a very high white blood cell count — 52,000. That’s a stress response, but we’re treating it like a possible infection just in case."
    },
    {
      "turn_number": 11,
      "time": "2136-12-24 06:17:00",
      "speaker": "Patient",
      "text": "Infection? From what?"
    },
    {
      "turn_number": 12,
      "time": "2136-12-24 06:19:00",
      "speaker": "Doctor",
      "text": "We don’t see bacteria in your bronchial wash, but we found acid-fast bacteria in the culture. It’s likely not TB, but we’re being cautious."
    },
    {
      "turn_number": 13,
      "time": "2136-12-24 06:21:00",
      "speaker": "Patient",
      "text": "So… not contagious?"
    },
    {
      "turn_number": 14,
      "time": "2136-12-24 06:23:00",
      "speaker": "Doctor",
      "text": "No, your sputum smears were negative three times. We’ve removed isolation precautions. It’s probably a slow-growing environmental type."
    },
    {
      "turn_number": 15,
      "time": "2136-12-24 06:25:00",
      "speaker": "Patient",
      "text": "What about my meds? Etanercept?"
    },
    {
      "turn_number": 16,
      "time": "2136-12-24 06:27:00",
      "speaker": "Doctor",
      "text": "We’re holding etanercept for now. Since you have this AFB finding, your rheumatologist and infectious disease will decide when it’s safe to restart."
    },
    {
      "turn_number": 17,
      "time": "2136-12-24 06:29:00",
      "speaker": "Patient",
      "text": "Okay… makes sense."
    },
    {
      "turn_number": 18,
      "time": "2136-12-24 10:00:00",
      "speaker": "Doctor",
      "text": "Your chest X-ray is clear — no pneumonia or collapse. That’s good. But your EKG showed some ST elevations."
    },
    {
      "turn_number": 19,
      "time": "2136-12-24 10:02:00",
      "speaker": "Patient",
      "text": "Heart attack?"
    },
    {
      "turn_number": 20,
      "time": "2136-12-24 10:04:00",
      "speaker": "Doctor",
      "text": "No. Your troponins are normal and the EKG looks like your old ones. It’s likely a chronic change from your past pericarditis."
    },
    {
      "turn_number": 21,
      "time": "2136-12-24 10:06:00",
      "speaker": "Patient",
      "text": "Relieved… I’ve been worried about that."
    },
    {
      "turn_number": 22,
      "time": "2136-12-25 07:00:00",
      "speaker": "Doctor",
      "text": "Your white count is coming down — now 24,000. Lactate is normal. You’re responding well to treatment."
    },
    {
      "turn_number": 23,
      "time": "2136-12-25 07:02:00",
      "speaker": "Patient",
      "text": "That’s good. What’s next?"
    },
    {
      "turn_number": 24,
      "time": "2136-12-25 07:04:00",
      "speaker": "Doctor",
      "text": "We’re switching from IV antibiotics to oral Augmentin for 10 days. It covers possible tracheal infection."
    },
    {
      "turn_number": 25,
      "time": "2136-12-25 07:06:00",
      "speaker": "Patient",
      "text": "Can I restart methotrexate?"
    },
    {
      "turn_number": 26,
      "time": "2136-12-25 07:08:00",
      "speaker": "Doctor",
      "text": "Not yet. Rheumatology says wait until after the antibiotics. Then you can restart on ___."
    },
    {
      "turn_number": 27,
      "time": "2136-12-25 07:10:00",
      "speaker": "Patient",
      "text": "Got it."
    },
    {
      "turn_number": 28,
      "time": "2136-12-26 08:00:00",
      "speaker": "Doctor",
      "text": "Your breathing is stronger. The plan is to start weaning your oxygen support today."
    },
    {
      "turn_number": 29,
      "time": "2136-12-26 08:02:00",
      "speaker": "Patient",
      "text": "Can I sit up more?"
    },
    {
      "turn_number": 30,
      "time": "2136-12-26 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll get you up in a chair. We also started a bowel regimen — docusate and senna — to prevent straining."
    },
    {
      "turn_number": 31,
      "time": "2136-12-26 08:06:00",
      "speaker": "Patient",
      "text": "Because of what happened?"
    },
    {
      "turn_number": 32,
      "time": "2136-12-26 08:08:00",
      "speaker": "Doctor",
      "text": "Exactly. Straining can increase pressure and worsen airway issues. We want to prevent another episode."
    },
    {
      "turn_number": 33,
      "time": "2136-12-26 08:10:00",
      "speaker": "Patient",
      "text": "Smart."
    },
    {
      "turn_number": 34,
      "time": "2136-12-27 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing great. Your labs are nearly normal. We’re planning for discharge tomorrow."
    },
    {
      "turn_number": 35,
      "time": "2136-12-27 09:02:00",
      "speaker": "Patient",
      "text": "Really? That’s fast."
    },
    {
      "turn_number": 36,
      "time": "2136-12-27 09:04:00",
      "speaker": "Doctor",
      "text": "Yes, because the procedure fixed the blockage and you’re healing well. But you’ll need to follow some instructions at home."
    },
    {
      "turn_number": 37,
      "time": "2136-12-27 09:06:00",
      "speaker": "Patient",
      "text": "Like what?"
    },
    {
      "turn_number": 38,
      "time": "2136-12-27 09:08:00",
      "speaker": "Doctor",
      "text": "Use the humidified trach mask at night. During the day, wear the HME filter. It keeps your airway moist and protected."
    },
    {
      "turn_number": 39,
      "time": "2136-12-27 09:10:00",
      "speaker": "Patient",
      "text": "I remember that from last time."
    },
    {
      "turn_number": 40,
      "time": "2136-12-27 09:12:00",
      "speaker": "Doctor",
      "text": "Good. You’ll also take prednisone — 50 mg for 3 days, then 40, then 30, 20, and finally 15 mg daily until you see your rheumatologist."
    },
    {
      "turn_number": 41,
      "time": "2136-12-27 09:14:00",
      "speaker": "Patient",
      "text": "And Bactrim with it?"
    },
    {
      "turn_number": 42,
      "time": "2136-12-27 09:16:00",
      "speaker": "Doctor",
      "text": "Yes, take Bactrim every day while on prednisone to prevent infection."
    },
    {
      "turn_number": 43,
      "time": "2136-12-27 09:18:00",
      "speaker": "Patient",
      "text": "And Augmentin until ___?"
    },
    {
      "turn_number": 44,
      "time": "2136-12-27 09:20:00",
      "speaker": "Doctor",
      "text": "Exactly. Finish all of it, then restart methotrexate the next day."
    },
    {
      "turn_number": 45,
      "time": "2136-12-27 09:22:00",
      "speaker": "Patient",
      "text": "What about the AFB result?"
    },
    {
      "turn_number": 46,
      "time": "2136-12-27 09:24:00",
      "speaker": "Doctor",
      "text": "We’re still waiting on full speciation. But you don’t need TB treatment. Just follow up with ID and rheumatology."
    },
    {
      "turn_number": 47,
      "time": "2136-12-28 10:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day. You’ve passed your swallow study — you can go back to thin liquids and regular food."
    },
    {
      "turn_number": 48,
      "time": "2136-12-28 10:02:00",
      "speaker": "Patient",
      "text": "No more thickened liquids?"
    },
    {
      "turn_number": 49,
      "time": "2136-12-28 10:04:00",
      "speaker": "Doctor",
      "text": "No. The study showed only minor penetration, no aspiration. Just stay upright for 30 minutes after eating."
    },
    {
      "turn_number": 50,
      "time": "2136-12-28 10:06:00",
      "speaker": "Patient",
      "text": "I can do that. Thank you, Doctor. I feel lucky to be here."
    },
    {
      "turn_number": 51,
      "time": "2136-12-28 10:08:00",
      "speaker": "Doctor",
      "text": "We’re glad you’re better. Keep up with your follow-ups, and call if you have any breathing trouble."
    },
    {
      "turn_number": 52,
      "time": "2136-12-28 10:10:00",
      "speaker": "Patient",
      "text": "I will. Thanks for everything."
    },
    {
      "turn_number": 53,
      "time": "2136-12-28 12:00:00",
      "speaker": "Doctor",
      "text": "Just a quick update — your swallow study confirmed mild dysphagia, but it’s stable. You’re cleared for your regular diet with precautions."
    },
    {
      "turn_number": 54,
      "time": "2136-12-28 12:02:00",
      "speaker": "Patient",
      "text": "Good to know. I was worried."
    },
    {
      "turn_number": 55,
      "time": "2136-12-28 14:00:00",
      "speaker": "Doctor",
      "text": "We’re finalizing your discharge. Home health will help with your trach care and check-ins."
    },
    {
      "turn_number": 56,
      "time": "2136-12-28 14:02:00",
      "speaker": "Patient",
      "text": "That’s a relief. I live alone."
    },
    {
      "turn_number": 57,
      "time": "2136-12-28 14:04:00",
      "speaker": "Doctor",
      "text": "Yes, they’ll make sure you’re safe. And your father will be checking in too, right?"
    },
    {
      "turn_number": 58,
      "time": "2136-12-28 14:06:00",
      "speaker": "Patient",
      "text": "Yes, he calls every day."
    },
    {
      "turn_number": 59,
      "time": "2136-12-28 16:00:00",
      "speaker": "Doctor",
      "text": "You’re all set. Remember: finish Augmentin, taper prednisone, restart methotrexate after, keep taking Bactrim with steroids, and use your HME and humidifier."
    },
    {
      "turn_number": 60,
      "time": "2136-12-28 16:02:00",
      "speaker": "Patient",
      "text": "Got it. I’ll follow the list."
    },
    {
      "turn_number": 61,
      "time": "2136-12-28 16:04:00",
      "speaker": "Doctor",
      "text": "And call if you have fever, trouble breathing, or chest pain. Otherwise, see your rheumatologist and pulmonologist soon."
    },
    {
      "turn_number": 62,
      "time": "2136-12-28 16:06:00",
      "speaker": "Patient",
      "text": "I will. Thank you again."
    },
    {
      "turn_number": 63,
      "time": "2136-12-28 16:08:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___. You’ve come a long way."
    },
    {
      "turn_number": 64,
      "time": "2136-12-28 16:10:00",
      "speaker": "Patient",
      "text": "Thanks for not giving up on me."
    },
    {
      "turn_number": 65,
      "time": "2136-12-28 16:12:00",
      "speaker": "Doctor",
      "text": "Never. You’re strong — keep it up."
    },
    {
      "turn_number": 66,
      "time": "2136-12-28 16:14:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 67,
      "time": "2136-12-28 16:16:00",
      "speaker": "Doctor",
      "text": "We’ll see you in follow-up. Safe travels home."
    }
  ],
  "summary": {
    "admission_start": "2136-12-24 02:19:00",
    "admission_end": "2136-12-28 18:30:00",
    "summary_paragraph": "Mr. ___ was admitted with acute hypercarbic respiratory failure due to tracheal occlusion from a fibrous clot, occurring the day after a prior discharge. He has a complex history of Ruvalcaba-Myhre-Smith syndrome and relapsing polychondritis with recurrent tracheal stenosis, requiring multiple prior dilations and a tracheostomy. He underwent urgent bronchoscopy and tracheal dilation, which relieved the obstruction. His elevated white count and lactate improved with supportive care and antibiotics. An acid-fast bacillus was cultured from BAL, but TB was ruled out; etanercept was held pending further evaluation. He was treated with a course of Augmentin, started on a prednisone taper, and maintained on Bactrim prophylaxis. A swallow study showed mild oropharyngeal dysphagia without aspiration, allowing return to baseline diet. He was discharged home with services on a steroid taper, antibiotics, and instructions to restart methotrexate after antibiotic completion.",
    "problems": [
      "Tracheal stenosis",
      "Hypercarbic respiratory failure",
      "Relapsing polychondritis",
      "Ruvalcaba-Myhre-Smith syndrome",
      "Dysphagia, oropharyngeal phase",
      "Gastro-esophageal reflux disease without esophagitis",
      "Essential (primary) hypertension",
      "Other specified diseases of upper respiratory tract",
      "Pneumonitis due to inhalation of food and vomit",
      "Acidosis"
    ]
  }
}
